def flatten(d: dict) -> dict:
    """
    Flattens one level of nested dicts, joining keys with a dot.

    Args:
        d: The dictionary to flatten.

    Returns:
        A new flattened dictionary.
    """
    flat_dict = {}
    for key, value in d.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                new_key = f"{key}.{sub_key}"
                flat_dict[new_key] = sub_value
        else:
            flat_dict[key] = value
    return flat_dict
